-- 00_PRECHECK_CLOUD.sql — 적용 전 클라우드 상태 점검 (조회 전용)
SET PAGESIZE 200 LINESIZE 300
COLUMN EXPECTED_MISSING FORMAT A120
COLUMN CLOUD_ONLY_MARKERS FORMAT A80

-- ① 객체 상태 + 사내 보완 마커 중 클라우드 누락분 / 클라우드 단독 마커
SELECT O.OBJECT_NAME, O.OBJECT_TYPE, O.STATUS, TO_CHAR(O.LAST_DDL_TIME,'YYYY-MM-DD HH24:MI:SS') LAST_DDL,
       (SELECT COUNT(*) FROM USER_SOURCE S WHERE S.NAME=O.OBJECT_NAME AND S.TYPE=O.OBJECT_TYPE) SRC_LINES,
       (SELECT LISTAGG(E.M,',') WITHIN GROUP (ORDER BY E.M) FROM (SELECT COLUMN_VALUE M FROM TABLE(SYS.ODCIVARCHAR2LIST('E20240812-000094','E20241126-000426','E20241217-000632','E20250522-001188','E20250714-000331','E20250729-000433','E20250825-000297','E20250912-001720','E20250915-000105','E20250919-001699','E20251021-000634','E20251208-000309','E20251209-000712','E20251223-000672','E20260107-001651','E20260130-001907','E20260309-000271','E20260608-000294','E20260805-AFS','E20260806-DS2','E20260812-DS2','E20260812-PERF','E20260813-EXCELFORM','E20260813-UPLOADSAVE','E20260814-CURMEASURE','E20260814-FCSTNAME','E20260815-PERF','E20260815-PERF2','E20260815-SENTINEL','E20260815-SPLIT2GTT','E20260819-LIMITMEAS','E20260819-MULTIJOIN','E20260819-PJTNAME','E20260819-SENDERJOIN','E20260819-XLS81LOC','E20260820-AFSNULL','E20260820-MEASRULE','E20260820-SENTINELDDL','E20260820-XLSSAVEPERF','E20260822-DIV81DEL','E20260822-KEYCOL','E20260822-LOCWEEKSUM','E20260824-PKGCONSOL','E20260825-81AUTH','E20260825-AFSBLANK','E20260825-AFSNVL','E20260825-CURRNORM','E20260825-CUSTSUB','E20260825-SAVEPOPCLOB','E20260825-SAVEPOPCLOB2','E20260825-SAVEPOPPERF','E20260825-SCPPLOC','E20260826-ASINSREQ','E20260826-AUTHVIEW','E20260826-CUSTSUBORPH','E20260826-CUSTSUBR','E20260826-SCPVMI','E20260831-NCHARUNION','E20260831-QTYKEY','E20260901-CURRKEEP','E20260901-MEASORDER','E20260901-SAVECLOB','E20260901-STATELESS','E20260902-81SCMFCST','E20260907-DEFFLAG','E20260907-LIMITMEAS','E20260907-PERF1','E20260907-PERF2','E20260908-ENDCUST','E20260908-GETRANGE','E20260915-BPSIFNODATA','E20260915-EXLASTUPD','E20260915-PRICEPJTGAP','E20260916-PRICEWEEK','E20260917-SAMESAVEDEL','E20260918-CURRCELLPROD','E20260918-CURRNULLKEY','E20260918-CURRSITEITEM','E20260918-KEYCOLGRAIN','E20260918-KEYCOLGRAIN2','E20260921-XLSFORMASIS','E20260922-MSGUNDERSCORE','E20260922-TMAINFIX','E20260923-XLSFORMCURCHAIN','E20260923-XLSFORMCURRENCY','E20260923-XLSFORMMEASUREOFF','E20260923-XLSFORMSORT'))) E
         WHERE NOT EXISTS (SELECT 1 FROM USER_SOURCE S WHERE S.NAME=O.OBJECT_NAME AND S.TYPE=O.OBJECT_TYPE AND INSTR(S.TEXT,E.M)>0)) EXPECTED_MISSING,
       (SELECT LISTAGG(X.M,',') WITHIN GROUP (ORDER BY X.M) FROM (SELECT DISTINCT REGEXP_SUBSTR(S.TEXT,'E20[0-9]{6}-[A-Z0-9_]+') M FROM USER_SOURCE S
          WHERE S.NAME=O.OBJECT_NAME AND S.TYPE=O.OBJECT_TYPE AND REGEXP_LIKE(S.TEXT,'E20[0-9]{6}-[A-Z0-9_]+')) X
         WHERE X.M NOT IN ('E20240812-000094','E20241126-000426','E20241217-000632','E20250522-001188','E20250714-000331','E20250729-000433','E20250825-000297','E20250912-001720','E20250915-000105','E20250919-001699','E20251021-000634','E20251208-000309','E20251209-000712','E20251223-000672','E20260107-001651','E20260130-001907','E20260309-000271','E20260608-000294','E20260805-AFS','E20260806-DS2','E20260812-DS2','E20260812-PERF','E20260813-EXCELFORM','E20260813-UPLOADSAVE','E20260814-CURMEASURE','E20260814-FCSTNAME','E20260815-PERF','E20260815-PERF2','E20260815-SENTINEL','E20260815-SPLIT2GTT','E20260819-LIMITMEAS','E20260819-MULTIJOIN','E20260819-PJTNAME','E20260819-SENDERJOIN','E20260819-XLS81LOC','E20260820-AFSNULL','E20260820-MEASRULE','E20260820-SENTINELDDL','E20260820-XLSSAVEPERF','E20260822-DIV81DEL','E20260822-KEYCOL','E20260822-LOCWEEKSUM','E20260824-PKGCONSOL','E20260825-81AUTH','E20260825-AFSBLANK','E20260825-AFSNVL','E20260825-CURRNORM','E20260825-CUSTSUB','E20260825-SAVEPOPCLOB','E20260825-SAVEPOPCLOB2','E20260825-SAVEPOPPERF','E20260825-SCPPLOC','E20260826-ASINSREQ','E20260826-AUTHVIEW','E20260826-CUSTSUBORPH','E20260826-CUSTSUBR','E20260826-SCPVMI','E20260831-NCHARUNION','E20260831-QTYKEY','E20260901-CURRKEEP','E20260901-MEASORDER','E20260901-SAVECLOB','E20260901-STATELESS','E20260902-81SCMFCST','E20260907-DEFFLAG','E20260907-LIMITMEAS','E20260907-PERF1','E20260907-PERF2','E20260908-ENDCUST','E20260908-GETRANGE','E20260915-BPSIFNODATA','E20260915-EXLASTUPD','E20260915-PRICEPJTGAP','E20260916-PRICEWEEK','E20260917-SAMESAVEDEL','E20260918-CURRCELLPROD','E20260918-CURRNULLKEY','E20260918-CURRSITEITEM','E20260918-KEYCOLGRAIN','E20260918-KEYCOLGRAIN2','E20260921-XLSFORMASIS','E20260922-MSGUNDERSCORE','E20260922-TMAINFIX','E20260923-XLSFORMCURCHAIN','E20260923-XLSFORMCURRENCY','E20260923-XLSFORMMEASUREOFF','E20260923-XLSFORMSORT')) CLOUD_ONLY_MARKERS
  FROM USER_OBJECTS O WHERE O.OBJECT_NAME='PKG_DMF0082' AND O.OBJECT_TYPE IN ('PACKAGE','PACKAGE BODY');

-- ② 현재 Excel Form 조건 2종 — measure(적용 전 'RTF_SYS_RP' 단일) · CURRENCY 폴백(적용 전 NVL(x,'')='')
SELECT LINE, TRIM(TEXT) TEXT FROM USER_SOURCE
 WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND (INSTR(TEXT,'RTF_SYS_RP')>0 AND INSTR(UPPER(TEXT),'SP.MEASURE')>0 OR INSTR(TEXT,'SP.CURRENCY')>0 OR INSTR(UPPER(TEXT),'ORDER BY DIVISION_ID')>0)
 ORDER BY LINE;

-- ③ 적용 후 예상 건수 — **합집합(RTF_SYS_RP + MKT_FCST)** 기준. 둘의 합이 양식 행수를 좌우한다.
--    RTF 가 8행 수준이어도 MKT_FCST 가 수천 행이면 양식은 채워진다(클라우드 진단 시 MKT_FCST 10,472).
SELECT MEASURE, COUNT(*) CNT FROM DM_PLN_SALES_PLAN_C
 WHERE DIVISION_ID='81' AND MEASURE IN ('RTF_SYS_RP','MKT_FCST')
   AND VERSION_NO=(SELECT MAX(VERSION_NO) FROM DM_MST_VERSION WHERE DIVISION_ID='81' AND VERSION_TYPE='SP_W')
 GROUP BY MEASURE;

-- ④ 컷오프 스냅샷 건전성 — 원장 대비 누락 measure (RTF_PR/SalesAmt_* 가 0 이면 컷오프 재수행 대상)
SELECT S.MEASURE, COUNT(*) AS 원장, (SELECT COUNT(*) FROM DM_PLN_SALES_PLAN_C C
   WHERE C.DIVISION_ID='81' AND C.MEASURE=S.MEASURE
     AND C.VERSION_NO=(SELECT MAX(VERSION_NO) FROM DM_MST_VERSION WHERE DIVISION_ID='81' AND VERSION_TYPE='SP_W')) AS 컷오프
  FROM DM_PLN_SALES_PLAN S
 WHERE S.DIVISION_ID='81' AND S.YYYYMMDD >= TO_CHAR(FN_NEXT_DAY(SYSDATE,'MON')-7,'YYYYMMDD')
 GROUP BY S.MEASURE ORDER BY 2 DESC;
